/**
 * A joined row of segments that always holds one value (`design/components/segmented-control.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/segmented-control.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, useContext, type JSX } from 'solid-js'

import * as zag from '@zag-js/radio-group'
import { normalizeProps } from '@zag-js/solid'

import {
  BORROWED,
  Each,
  IDENTITY,
  Icon,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  provide,
  roveRadio,
  scope,
  useDirection,
  useMachine,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/segmented-control.module.css'

export type SegmentedControlSize = NonNullable<SegmentedControlProps['size']>

export interface SegmentedControlOption {
  value: string
  label: string
  icon?: IconRole
  disabled?: boolean
}

export interface SegmentedControlProps {
  defaultValue?: string
  /**
   * Disables the whole group. Use `disabled` in `options` for single options.
   */
  disabled?: boolean
  /**
   * The group's accessible name, because outside a form there is no FormField to name it.
   */
  label: string
  onChange?: (value: string) => void
  /**
   * Items render from data, because free-form children invite ad hoc layouts (Radio's law).
   */
  options: SegmentedControlOption[]
  /**
   * There is no `lg`, on purpose. A segmented control is an inline control used in toolbars,
   * page headers and filter rows next to `sm`/`md` controls. A form-sized single choice is
   * RadioGroup in a FormField, not this at 44px.
   */
  size?: 'sm' | 'md'
  value?: string
}

/** A joined row of segments that always holds one value. */
export default function SegmentedControl(given: SegmentedControlProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', disabled: false } as Defaults<SegmentedControlProps, 'size' | 'disabled'>,
    claimSlot(given),
  )
  const lent = useContext(IDENTITY)
  const lender = useContext(BORROWED)
  return scope(() => {
    provide(BORROWED, undefined)
    const uid = createUniqueId()
    const track = elementRef<HTMLElement>()
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          value: props.value,
          defaultValue: props.defaultValue ?? props.options[0]?.value,
          disabled: props.disabled,
          onValueChange: (details) => {
            props.onChange?.(details.value ?? '')
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const stop = createDerived(
      () =>
        api.value.value ??
        props.options.find((option) => !(props.disabled || option.disabled === true))?.value,
    )
    const effect1 = () => {
      void (lender && (lender.element = () => track.value))
    }
    onMount(effect1)
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'SegmentedControl',
        element: () => track.value,
        state: () => ({
          value: api.value.value ?? null,
          options: props.options.map((option) => ({
            id: option.value,
            label: option.label,
            ...(option.disabled === true ? { disabled: true } : {}),
          })),
          disabled: props.disabled,
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) => value !== api.value.value && api.value.setValue(value),
          },
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        class={styles.track}
        role="radiogroup"
        aria-label={props.label}
        data-size={props.size}
        data-disabled={props.disabled ? '' : undefined}
        data-member={lent ?? 'segmented-control'}
        ref={track.attach}
      >
        <Each of={props.options} by={(option) => option.value} renew>
          {(option) => (
            <button
              class={styles.segment}
              type="button"
              role="radio"
              value={option.value}
              aria-checked={api.value.value === option.value}
              disabled={props.disabled || option.disabled === true}
              tabindex={option.value === stop.value ? 0 : -1}
              data-state={api.value.value === option.value ? 'checked' : 'unchecked'}
              data-disabled={props.disabled || option.disabled === true ? '' : undefined}
              onclick={() => api.value.setValue(option.value)}
              onkeydown={($event: KeyboardEvent) =>
                $event.key === 'Enter'
                  ? $event.preventDefault()
                  : roveRadio($event, (next) => api.value.setValue(next))
              }
            >
              {api.value.value === option.value ? (
                <span class={styles.chip} data-state="checked" />
              ) : null}
              {option.icon !== undefined ? (
                <span class={styles.glyph}>
                  <Icon name={option.icon} size={props.size} />
                </span>
              ) : null}
              <span class={styles.label}>{option.label}</span>
            </button>
          )}
        </Each>
      </div>
    )
  })
}
